import re

# Helpers
def node_by_title(doc, title):
    for n in doc['nodes']:
        if n.get('title') == title:
            return n
    return None

def children(doc, node):
    return [node_by_id(doc, cid) for cid in node.get('children', [])]

def node_by_id(doc, node_id):
    for n in doc['nodes']:
        if n.get('node_id') == node_id:
            return n
    return None

def table_rows(node):
    rows = []
    for ri, row in enumerate(node['table']['rows']):
        row_dict = {c: row[i] for i, c in enumerate(node['table']['columns'])}
        rows.append((ri, row_dict))
    return rows

# Step 1 of 2 – reading functions -------------------------------------------------

def entities(doc, scope):
    """
    Every distinct entity in the scope.
    Here we consider each product as an entity.
    """
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []

    # Find Products table within this scope
    prod_node = None
    for cid in scope_node.get('children', []):
        child = node_by_id(doc, cid)
        if child and child['kind'] == 'table' and child['title'].endswith(': Products'):
            prod_node = child
            break
    if not prod_node:
        return []

    ents = []
    for _, r in table_rows(prod_node):
        prod_id = r['product']
        ents.append({"id": prod_id, "description": prod_id})
    return ents

def recorded_end(doc, scope):
    """
    Last day number in the Daily ledger table.
    """
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return None

    ledger_node = None
    for cid in scope_node.get('children', []):
        child = node_by_id(doc, cid)
        if child and child['kind'] == 'table' and child['title'].endswith(': Daily ledger'):
            ledger_node = child
            break
    if not ledger_node:
        return None

    max_day = None
    for _, r in table_rows(ledger_node):
        try:
            d = int(r['day'])
        except ValueError:
            continue
        if max_day is None or d > max_day:
            max_day = d
    return max_day

def inputs(doc, scope):
    """
    Returns all recorded inputs for the scope.
    """
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []

    inputs = []

    # ---------- Opening stock ----------
    prod_node = None
    for cid in scope_node.get('children', []):
        child = node_by_id(doc, cid)
        if child and child['kind'] == 'table' and child['title'].endswith(': Products'):
            prod_node = child
            break

    if prod_node:
        for ri, r in table_rows(prod_node):
            prod_id = r['product']
            try:
                stock = int(r['opening stock'])
            except (ValueError, KeyError):
                continue
            inputs.append({
                "id": f"{prod_id}_open",
                "time": None,
                "kind": "opening_stock",
                "entities": [prod_id],
                "fields": {"units": stock},
                "src": [[prod_node['node_id'], ri, ["opening stock"]]]
            })

    # ---------- Daily production and orders ----------
    ledger_node = None
    for cid in scope_node.get('children', []):
        child = node_by_id(doc, cid)
        if child and child['kind'] == 'table' and child['title'].endswith(': Daily ledger'):
            ledger_node = child
            break

    if ledger_node:
        for ri, r in table_rows(ledger_node):
            prod_id = r['product']
            day = None
            try:
                day = int(r['day'])
            except ValueError:
                continue
            # Produced
            try:
                prod = int(r['produced'])
            except (ValueError, KeyError):
                prod = None
            if prod is not None:
                inputs.append({
                    "id": f"{prod_id}_prod_{day}",
                    "time": day,
                    "kind": "production",
                    "entities": [prod_id],
                    "fields": {"units": prod},
                    "src": [[ledger_node['node_id'], ri, ["produced"]]]
                })
            # Ordered
            try:
                order = int(r['ordered'])
            except (ValueError, KeyError):
                order = None
            if order is not None:
                inputs.append({
                    "id": f"{prod_id}_order_{day}",
                    "time": day,
                    "kind": "order",
                    "entities": [prod_id],
                    "fields": {"units": order},
                    "src": [[ledger_node['node_id'], ri, ["ordered"]]]
                })

    # ---------- Future Order book ----------
    ob_node = None
    for cid in scope_node.get('children', []):
        child = node_by_id(doc, cid)
        if child and child['kind'] == 'table' and child['title'].endswith(': Order book'):
            ob_node = child
            break

    if ob_node:
        for ri, r in table_rows(ob_node):
            prod_id = r['product']
            day = None
            try:
                day = int(r['day placed'])
            except ValueError:
                continue
            try:
                units = int(r['units still open'])
            except (ValueError, KeyError):
                units = None
            if units is not None:
                inputs.append({
                    "id": f"{prod_id}_obook_{day}",
                    "time": day,
                    "kind": "future_order",
                    "entities": [prod_id],
                    "fields": {"units": units},
                    "src": [[ob_node['node_id'], ri]]
                })

    return inputs

def outcomes(doc, scope):
    """
    Returns all recorded outcomes for the scope.
    """
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []

    outcomes = []

    # ---------- Ledger result quantities ----------
    ledger_node = None
    for cid in scope_node.get('children', []):
        child = node_by_id(doc, cid)
        if child and child['kind'] == 'table' and child['title'].endswith(': Daily ledger'):
            ledger_node = child
            break

    if ledger_node:
        for ri, r in table_rows(ledger_node):
            prod_id = r['product']
            try:
                day = int(r['day'])
            except ValueError:
                continue
            # shipped
            try:
                shipped = int(r['shipped'])
            except (ValueError, KeyError):
                shipped = None
            if shipped is not None:
                outcomes.append({
                    "time": day,
                    "kind": "shipped",
                    "entities": [prod_id],
                    "value": shipped,
                    "src": [[ledger_node['node_id'], ri, ["shipped"]]]
                })
            # backordered
            try:
                back = int(r['backordered'])
            except (ValueError, KeyError):
                back = None
            if back is not None:
                outcomes.append({
                    "time": day,
                    "kind": "backordered",
                    "entities": [prod_id],
                    "value": back,
                    "src": [[ledger_node['node_id'], ri, ["backordered"]]]
                })
            # stock
            try:
                stock = int(r['stock'])
            except (ValueError, KeyError):
                stock = None
            if stock is not None:
                outcomes.append({
                    "time": day,
                    "kind": "stock",
                    "entities": [prod_id],
                    "value": stock,
                    "src": [[ledger_node['node_id'], ri, ["stock"]]]
                })

    # ---------- Events ----------
    for cid in scope_node.get('children', []):
        child = node_by_id(doc, cid)
        if not child:
            continue
        if child['kind'] == 'list' and child['title'].endswith(': Events'):
            for li, line in enumerate(child['lines']):
                # Extract day column from the line
                m_day = re.search(r'Day\s+(\d+)', line)
                day = int(m_day.group(1)) if m_day else None
                # Find product id if present
                p_match = re.search(r'([A-Z0-9\-]{3,})', line)
                product = p_match.group(1) if p_match else None
                entities = [product] if product else []
                outcomes.append({
                    "time": day,
                    "kind": "event",
                    "entities": entities,
                    "value": None,
                    "src": [[child['node_id'], li]]
                })
        # Text nodes with events can also contain events, treat as list of lines
        if child['kind'] == 'text' and child['title'].endswith(': Events'):
            lines = child['text'].splitlines()
            for li, line in enumerate(lines):
                m_day = re.search(r'Day\s+(\d+)', line)
                day = int(m_day.group(1)) if m_day else None
                p_match = re.search(r'([A-Z0-9\-]{3,})', line)
                product = p_match.group(1) if p_match else None
                entities = [product] if product else []
                outcomes.append({
                    "time": day,
                    "kind": "event",
                    "entities": entities,
                    "value": None,
                    "src": [[child['node_id'], li]]
                })
    return outcomes

