import re
from typing import Any, Dict, List, Tuple

# --------------------------------------------------------------------
# Helpers already provided in the environment
# --------------------------------------------------------------------
def node_by_title(doc: Dict[str, Any], title: str) -> Dict[str, Any] | None:
    return next((n for n in doc.get("nodes", []) if n.get("title") == title), None)


def node_by_id(doc: Dict[str, Any], node_id: str) -> Dict[str, Any] | None:
    return next((n for n in doc.get("nodes", []) if n.get("node_id") == node_id), None)


def children(doc: Dict[str, Any], node: Dict[str, Any]) -> List[Dict[str, Any]]:
    return [node_by_id(doc, cid) for cid in node.get("children", []) if node_by_id(doc, cid)]


def table_rows(node: Dict[str, Any]) -> List[Tuple[int, Dict[str, str]]]:
    rows: List[Tuple[int, Dict[str, str]]] = []
    tbl = node.get("table", {})
    cols = tbl.get("columns", [])
    for ri, row in enumerate(tbl.get("rows", [])):
        rows.append((ri, {c: row[i] for i, c in enumerate(cols)}))
    return rows
# --------------------------------------------------------------------


# --------------------------------------------------------------------
# Public functions required by the specification
# --------------------------------------------------------------------
def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, str]]:
    """Return every distinct product entity in the scope."""
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []

    prod_ids: set[str] = set()

    for child in children(doc, scope_node):
        if child.get("kind") != "table":
            continue
        for _, row in table_rows(child):
            # product column may be named 'product', case‑insensitive
            for col_name, value in row.items():
                if col_name.lower() == "product" and value:
                    prod_ids.add(value)

    return [{"id": pid, "description": pid} for pid in sorted(prod_ids)]


def recorded_end(doc: Dict[str, Any], scope: str) -> float | None:
    """Last day number recorded in the 'Daily ledger' table."""
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return None

    ledger_node = next(
        (c for c in children(doc, scope_node) if c.get("kind") == "table" and c.get("title", "").endswith(": Daily ledger")),
        None,
    )
    if not ledger_node:
        return None

    max_day = None
    for _, r in table_rows(ledger_node):
        try:
            d = int(r.get("day", ""))
            if max_day is None or d > max_day:
                max_day = d
        except Exception:
            continue

    return float(max_day) if max_day is not None else None


