                continue

            try:
                prod_qty = int(r.get(prod_qty_col, 0))
            except Exception:
                prod_qty = 0
            if prod_qty:
                inps.append(
                    {
                        "id": f"{prod}_prod_{day}",
                        "time": day,
                        "kind": "production",
                        "entities": [prod],
                        "fields": {"units": prod_qty},
                        "src": [[ledger_node["node_id"], ri, [prod_qty_col]]],
                    }
                )

            try:
                order_qty = int(r.get(order_qty_col, 0))
            except Exception:
                order_qty = 0
            if order_qty:
                inps.append(
                    {
                        "id": f"{prod}_order_{day}",
                        "time": day,
                        "kind": "order",
                        "entities": [prod],
                        "fields": {"units": order_qty},
                        "src": [[ledger_node["node_id"], ri, [order_qty_col]]],
                    }
                )

    # 3. Planned orders (Order book tables)
    for child in children(doc, scope_node):
        if child.get("kind") != "table":
            continue
        if not child.get("title", "").endswith(": Order book"):
            continue
        col_map = {c.strip().lower(): c for c in child.get("table", {}).get("columns", [])}
        prod_col = col_map.get("product")
        day_col = col_map.get("day placed") or col_map.get("day")
        units_col = col_map.get("units still open")
        if not prod_col or not day_col or not units_col:
            continue
        for ri, r in table_rows(child):
            prod = r.get(prod_col)
            if not prod:
                continue
            try:
                day = int(r.get(day_col, ""))
            except Exception:
                continue
            try:
                units = int(r.get(units_col, 0))
            except Exception:
                units = 0
            if units:
                inps.append(
                    {
                        "id": f"{prod}_obook_{day}",
                        "time": day,
                        "kind": "future_order",
                        "entities": [prod],
                        "fields": {"units": units},
                        "src": [[child["node_id"], ri, [units_col]]],
                    }
                )

    return inps


def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """All quantities and events produced by the process."""
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []

    # Get the set of known product entities for filtering
    entity_ids = {e["id"] for e in entities(doc, scope)}

    outs: List[Dict[str, Any]] = []

    # 1. Result quantities from Daily ledger
    ledger_node = next(
        (
            c
            for c in children(doc, scope_node)
            if c.get("kind") == "table" and c.get("title", "").endswith(": Daily ledger")
        ),
        None,
    )
    if ledger_node:
        col_map = {c.strip().lower(): c for c in ledger_node.get("table", {}).get("columns", [])}
        prod_col = col_map.get("product")
        day_col = col_map.get("day")
        shipped_col = col_map.get("shipped")
        back_col = col_map.get("backordered")
        stock_col = col_map.get("stock")

        for ri, r in table_rows(ledger_node):
            prod = r.get(prod_col)
            if not prod or prod not in entity_ids:
                continue
            try:
                day = int(r.get(day_col, ""))
            except Exception:
                continue

            # shipped
            try:
                shipped = int(r.get(shipped_col, 0))
                if shipped is not None:
                    outs.append(
                        {
                            "time": day,
                            "kind": "shipped",
                            "entities": [prod],
                            "value": shipped,
                            "src": [[ledger_node["node_id"], ri, [shipped_col]]],
                        }
                    )
            except Exception:
                pass

            # backordered
            try:
                back = int(r.get(back_col, 0))
                if back is not None:
                    outs.append(
                        {
                            "time": day,
                            "kind": "backordered",
                            "entities": [prod],
                            "value": back,
                            "src": [[ledger_node["node_id"], ri, [back_col]]],
                        }
                    )
            except Exception:
                pass

            # stock
            try:
                stock = int(r.get(stock_col, 0))
                if stock is not None:
                    outs.append(
                        {
                            "time": day,
                            "kind": "stock",
                            "entities": [prod],
                            "value": stock,
                            "src": [[ledger_node["node_id"], ri, [stock_col]]],
                        }
                    )
            except Exception:
                pass

    # 2. Events from Events list/text
    for child in children(doc, scope_node):
        if child.get("kind") == "list":
            for li, line in enumerate(child.get("lines", [])):
                day = None
                m = re.search(r"Day\s+(\d+)", line)
                if m:
                    try:
                        day = int(m.group(1))
                    except Exception:
                        pass
                # Pull any product codes that begin with a letter
                prods_found = re.findall(r"\b[A-Z][A-Z0-9\-]*\b", line)
                prods = [p for p in prods_found if p in entity_ids]
                outs.append(
                    {
                        "time": day,
                        "kind": "event",
                        "entities": prods,
                        "value": None,
                        "src": [[child["node_id"], li]],
                    }
                )
        elif child.get("kind") == "text":
            for li, line in enumerate(child.get("text", "").splitlines()):
                day = None
                m = re.search(r"Day\s+(\d+)", line)
                if m:
                    try:
                        day = int(m.group(1))
                    except Exception:
                        pass
                prods_found = re.findall(r"\b[A-Z][A-Z0-9\-]*\b", line)
                prods = [p for p in prods_found if p in entity_ids]
                outs.append(
                    {
                        "time": day,
                        "kind": "event",
                        "entities": prods,
                        "value": None,
                        "src": [[child["node_id"], li]],
                    }
                )

    return outs


def params(doc: Dict[str, Any], scope: str) -> Dict[str, Any]:
    """Constants specified in the scope."""
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return {}

    params: Dict[str, Any] = {}

    for child in children(doc, scope_node):
        if child.get("kind") != "text":
            continue
        m = re.search(r"Daily dispatch capacity:\s+(\d+)", child.get("text", ""))
        if m:
            params["dispatch_capacity"] = int(m.group(1))
    return params
